'use strict';
const config=window.THECOCO_CONFIG||{};
const products={syrup:{name:'코코넛 꽃 시럽',en:'COCONUT FLOWER NECTAR',image:'assets/syrup.webp',description:'코코넛 꽃에서 채취한 수액을 농축한 속팜의 시럽. 음식과 음료에 자연스러운 단맛을 더하는 새로운 식재료입니다.',use:'요거트와 토스트에 곁들이거나, 음료·베이킹·요리 양념에 사용해 보세요.'},sugar:{name:'코코넛 꽃 설탕',en:'COCONUT FLOWER SUGAR',image:'assets/sugar.webp',description:'코코넛 꽃 수액으로 만든 속팜의 설탕. 매일의 음료와 디저트에 색다른 달콤함을 더합니다.',use:'커피와 차, 쿠키와 케이크, 단맛이 필요한 요리에 취향에 맞게 넣어보세요.'},aminos:{name:'코코넛 꽃 발효소스',en:'COCONUT AMINOS',image:'assets/aminos.webp',description:'코코넛 꽃 수액과 소금으로 만드는 발효 조미소스. 재료 본연의 맛과 어울리는 풍미를 전합니다.',use:'소스로 곁들이거나 볶음·조림·드레싱 등 다양한 요리에 활용해 보세요.'},nectar:{name:'코코넛 꽃 수액 음료',en:'COCONUT BLOSSOM DRINK',image:'assets/nectar.webp',description:'코코넛 꽃에서 채취한 수액을 담은 속팜의 음료. 코코넛 꽃의 또 다른 맛을 편하게 만나보세요.',use:'제품에 표시된 보관법과 음용 안내에 따라 즐겨보세요.'}};
const productDialog=document.getElementById('product-dialog'),infoDialog=document.getElementById('info-dialog');let lastFocus=null;
function validUrl(value){try{const u=new URL(value);return u.protocol==='https:'?u.href:null}catch{return null}}
function openDialog(dialog){const prior=document.activeElement;if(!prior.closest('dialog'))lastFocus=prior;document.querySelectorAll('dialog[open]').forEach(d=>d.close());dialog.showModal();document.body.classList.add('modal-open');}
function closeDialog(dialog){dialog.close();document.body.classList.remove('modal-open');if(lastFocus&&lastFocus.isConnected)lastFocus.focus();}
function info(title,message){document.getElementById('info-title').textContent=title;document.getElementById('info-description').textContent=message;openDialog(infoDialog);}
function productDetail(key){const p=products[key];if(!p)return;document.getElementById('detail-en').textContent=p.en;document.getElementById('detail-title').textContent=p.name;document.getElementById('detail-description').textContent=p.description;document.getElementById('detail-use').textContent=p.use;const img=document.getElementById('detail-img');img.src=p.image;img.alt=p.name;const link=document.getElementById('detail-shop');link.dataset.shopProduct=key;link.href=validUrl(config.productUrls?.[key]||config.shopUrl)||'#store';openDialog(productDialog);}
document.querySelectorAll('[data-product]').forEach(b=>b.addEventListener('click',()=>productDetail(b.dataset.product)));
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>closeDialog(b.closest('dialog'))));
document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('cancel',()=>document.body.classList.remove('modal-open'));d.addEventListener('click',e=>{const r=d.getBoundingClientRect();if(e.target===d&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))closeDialog(d)});});
document.querySelectorAll('[data-shop]').forEach(link=>{const url=validUrl(config.shopUrl);if(url)link.href=url;link.addEventListener('click',e=>{const key=link.dataset.shopProduct;const target=validUrl((key&&config.productUrls?.[key])||config.shopUrl);if(target){link.href=target;return;}e.preventDefault();info('공식 스토어 오픈 준비 중','더코코의 제품을 구매하실 수 있는 공식 스토어를 준비하고 있습니다. 오픈 후 이곳에서 구매와 결제를 이용하실 수 있습니다.');});});
document.querySelectorAll('[data-contact]').forEach(b=>b.addEventListener('click',()=>{const url=validUrl(config.contactUrl);if(url){window.location.assign(url);return;}info('더코코 비즈니스 안내','프리미엄 유통·납품 파트너를 위한 공식 상담 채널을 준비하고 있습니다. 연락처가 확정되는 대로 이곳에서 안내해 드리겠습니다.');}));
const menuButton=document.querySelector('.menu-button'),mobileMenu=document.getElementById('mobile-menu');
function closeMenu(){menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','메뉴 열기');mobileMenu.hidden=true;document.body.classList.remove('menu-open')}
menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'메뉴 닫기':'메뉴 열기');mobileMenu.hidden=!open;document.body.classList.toggle('menu-open',open);});
mobileMenu.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menuButton.getAttribute('aria-expanded')==='true'){closeMenu();menuButton.focus();}});window.matchMedia('(min-width:768px)').addEventListener('change',e=>{if(e.matches)closeMenu()});
const slides=[{title:'좋은 취향은,<br>좋은 원료에서.',description:'한 잔의 커피, 한 접시의 디저트.<br>코코넛 꽃에서 시작되는 섬세한 미식.',cta:'컬렉션 만나보기',href:'#products'},{title:'코코넛 꽃에서,<br>당신의 식탁까지.',description:'홈카페의 달콤함부터 채소 요리의 풍미까지.<br>일상의 취향에 맞춰 고르는 코코넛 꽃 원료.',cta:'제품 만나보기',href:'#products'}];
document.querySelectorAll('[data-slide]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.slide),s=slides[i];document.getElementById('hero-title').innerHTML=s.title;document.getElementById('hero-desc').innerHTML=s.description;const a=document.getElementById('hero-cta');a.textContent=s.cta;a.href=s.href;document.querySelector('.hero').classList.toggle('second',i===1);document.querySelectorAll('[data-slide]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});const copy=document.querySelector('.hero-copy');copy.classList.remove('changing');void copy.offsetWidth;copy.classList.add('changing');}));
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{const filter=b.dataset.filter;let count=0;document.querySelectorAll('.product-card').forEach(card=>{card.hidden=filter!=='all'&&card.dataset.category!==filter;if(!card.hidden)count++});document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});document.getElementById('filter-status').textContent=b.textContent+' 제품 '+count+'개';}));
const moments=[{scene:'assets/chef-dessert-v2.webp',sceneAlt:'셰프가 디저트에 시럽을 더하는 활용 연출 장면',word:'Dining',index:'01 / HOTEL & FINE DINING',title:'마지막 한 스푼까지,<br>섬세하게 완성하는 맛.',description:'디저트와 브런치, 다이닝의 소스에 코코넛 꽃 시럽을 활용해 보세요. 메뉴의 개성을 표현하는 새로운 감미 재료를 제안합니다.',product:'syrup'},{scene:'assets/cafe-ritual-v2.webp',sceneAlt:'카페에서 커피와 디저트를 즐기는 고객의 연출 장면',word:'Café',index:'02 / PREMIUM CAFÉ',title:'한 잔의 인상을,<br>더 깊고 특별하게.',description:'커피와 시그니처 음료, 파티스리에 코코넛 꽃 설탕을 더해 보세요. 브랜드만의 풍미를 고민하는 카페를 위한 원료 제안입니다.',product:'sugar'},{scene:'assets/plant-table-v2.webp',sceneAlt:'집에서 버섯과 두부, 채소 요리를 즐기는 연출 장면',word:'Selection',index:'03 / SELECTED RETAIL',title:'취향을 아는 고객을 위한<br>새로운 식품 큐레이션.',description:'원료의 출처와 쓰임이 분명한 코코넛 꽃 발효소스. 프리미엄 식품관과 고메 리테일에서 소개할 새로운 식재료를 제안합니다.',product:'aminos'}];
const tabs=[...document.querySelectorAll('[data-moment]')];
function selectMoment(i,focus=false){const m=moments[i],p=products[m.product];document.getElementById('moment-index').textContent=m.index;document.getElementById('moment-title').innerHTML=m.title;document.getElementById('moment-description').textContent=m.description;document.querySelector('.moment-word').textContent=m.word;const img=document.getElementById('moment-img');img.src=p.image;img.alt=p.name;const scene=document.getElementById('moment-scene-img');scene.src=m.scene;scene.alt=m.sceneAlt;document.getElementById('moment-product-name').textContent=p.name;document.getElementById('moment-detail').dataset.product=m.product;tabs.forEach((t,n)=>{t.classList.toggle('active',n===i);t.setAttribute('aria-selected',String(n===i));t.tabIndex=n===i?0:-1});document.getElementById('moment-panel').setAttribute('aria-labelledby',tabs[i].id);if(focus)tabs[i].focus();}
tabs.forEach((t,i)=>{t.addEventListener('click',()=>selectMoment(i));t.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;else if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();selectMoment(next,true);}});});
